function undoLast(){
  const tx = state.lastTx; if(!tx || tx.undone) return;
  if(tx.op==='policy'){ const g=groupById(tx.groupId); g.policy=tx.beforePolicy; g.policyNote=tx.beforeNote; }
  else {
    for(let i=tx.entries.length-1;i>=0;i--){ const en=tx.entries[i]; const e=en.entity;
      if(tx.op==='delete'){ state.entities.splice(Math.min(en.index, state.entities.length),0,e); }
      e.ownStatus=en.before.ownStatus; e.groupId=en.before.groupId; e.tags=[...en.before.tags];
    }
  }
  tx.undone=true; state.lastTx=null;
  render(); showToast('已撤销：'+tx.opLabel);
}
