      '</div><div class="sub">' + e.id + ' · ' + esc(e.type) + ' ' + esc(e.model) + '</div></td>' +
    '<td class="c-grp"><div class="grp">' + esc(grp.name) + '</div><div class="sub">' + esc(region) + '</div></td>' +
    '<td class="c-owner">' + esc(e.owner) + '</td>' +
