    '<td class="c-lock"><button class="lock-btn' + (e.locked ? ' on' : '') + '" data-id="' + e.id + '" title="' +
      (e.locked ? '受保护：批量写操作默认跳过 — 点击取消保护' : '保护该设备（批量写操作默认跳过）') + '">' +
      (e.locked ? '🛡' : '○') + '</button></td>' +
