    var html = '<div class="sel-big"><b>' + n + '</b><span>台设备已选</span></div>';
    if (protSel > 0) {
      html += '<div class="sel-prot">🛡 其中 ' + protSel + ' 台受保护，批量写操作默认跳过</div>';
