        '<div class="chips">' + b.items.map(function (e) {
          return '<button class="chip" data-id="' + e.id + '" title="点击移出选择">' + esc(e.name) + ' <i>×</i></button>';
        }).join('') + '</div>';
    }).join('') + '</div>';
