    var m = STATUS_META[e.ownStatus];
    return '<button class="own-st st ' + m.cls + '" data-id="' + e.id + '" title="点击修改自身状态">' + m.label + '</button>';
  }
  return '<button class="own-st st follow" data-id="' + e.id + '" title="未单独设定，点击为该设备设置自身状态">跟随上级</button>';
