1	/* AssetGrid — 应用逻辑（无框架、无构建、无网络请求） */
2	(function () {
3	'use strict';
4	
5	var D = window.DATA;
6	var STATUS_META = D.STATUS_META;
7	var STATUS_ORDER = D.STATUS_ORDER;
8	var DEFAULT_STATUS = D.DEFAULT_STATUS;
9	
10	/* ================= 工具 ================= */
11	function $(sel, root) { return (root || document).querySelector(sel); }
12	function $$(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
13	function el(tag, cls, html) {
14	  var n = document.createElement(tag);
15	  if (cls) n.className = cls;
16	  if (html != null) n.innerHTML = html;
17	  return n;
18	}
19	function esc(s) {
20	  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
21	    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
22	  });
23	}
24	function groupById(id) {
25	  for (var i = 0; i < D.GROUPS.length; i++) if (D.GROUPS[i].id === id) return D.GROUPS[i];
26	  return null;
27	}
28	function chain(id) { // 自身 → 根
29	  var out = [], g = groupById(id);
30	  while (g) { out.push(g); g = g.parent ? groupById(g.parent) : null; }
31	  return out;
32	}
33	function isWithin(gid, ancestorId) {
34	  return chain(gid).some(function (g) { return g.id === ancestorId; });
35	}
36	function groupPathLabel(gid) {
37	  return chain(gid).reverse().map(function (g) { return g.name; }).join(' › ');
38	}
39	function statusLabel(v) { return STATUS_META[v] ? STATUS_META[v].label : String(v); }
40	function pad2(n) { return n < 10 ? '0' + n : '' + n; }
41	function fmtTime(d) { return pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds()); }
42	function byId(id) {
43	  for (var i = 0; i < state.entities.length; i++) if (state.entities[i].id === id) return state.entities[i];
44	  return null;
45	}
46	
47	/* ================= 状态 ================= */
48	var state = {
49	  entities: D.ENTITIES.slice(),
50	  selection: new Set(),
51	  scopeMode: 'direct',          // 分组勾选范围：direct 仅直属 | all 含子孙
52	  focus: 'ALL',                 // 表格关注的分组子树
53	  search: '',
54	  statusFilter: 'ALL',
55	  onlySelected: false,
56	  expanded: new Set(D.GROUPS.map(function (g) { return g.id; })),
57	  log: [],                      // 事务日志（新→旧）
58	  lastTx: null,                 // 最近一次可撤销事务
59	  txSeq: 0,
60	  confirm: null,                // 批量操作确认单
61	  policyModal: null,            // 分组策略弹窗
62	  drawerOpen: false,
63	  result: null                  // 操作结果卡片
64	};
65	
66	var OPS = {
67	  status: { label: '修改状态' },
68	  move:   { label: '移动分组' },
69	  tag:    { label: '添加标签' },
70	  delete: { label: '删除设备' }
71	};
72	
73	/* 生效状态：自身状态 > 最近的分组策略 > 系统默认（policyOverride 用于策略模拟预览） */
74	function effective(e, policyOverride) {
75	  if (e.ownStatus) return { value: e.ownStatus, kind: 'own', label: '自身设定', detail: '' };
76	  var arr = chain(e.groupId);
77	  for (var i = 0; i < arr.length; i++) {
78	    var g = arr[i];
79	    var pol = (policyOverride && policyOverride.groupId === g.id) ? policyOverride.value : g.policy;
80	    if (pol) return { value: pol, kind: 'group', label: '继承 · ' + g.name, detail: g.policyNote || '' };
81	  }
82	  return { value: DEFAULT_STATUS, kind: 'default', label: '系统默认', detail: '' };
83	}
84	function effPreviewValue(e, newOwnStatus, policyOverride) {
85	  var clone = Object.assign({}, e, { ownStatus: newOwnStatus });
86	  return effective(clone, policyOverride).value;
87	}
88	function resolveGroup(gid, mode) {
89	  return state.entities.filter(function (e) {
90	    return mode === 'all' ? isWithin(e.groupId, gid) : e.groupId === gid;
91	  }).map(function (e) { return e.id; });
92	}
93	function visibleEntities() {
94	  var list = state.entities;
95	  if (state.focus !== 'ALL') list = list.filter(function (e) { return isWithin(e.groupId, state.focus); });
96	  var q = state.search.trim().toLowerCase();
97	  if (q) {
98	    list = list.filter(function (e) {
99	      return (e.name + ' ' + e.id + ' ' + e.type + ' ' + e.model + ' ' + e.owner + ' ' + e.tags.join(' '))
100	        .toLowerCase().indexOf(q) >= 0;
101	    });
102	  }
103	  if (state.statusFilter !== 'ALL') {
104	    list = list.filter(function (e) {
105	      var ef = effective(e);
106	      if (state.statusFilter === 'override') return ef.kind === 'own';
107	      return ef.value === state.statusFilter;
108	    });
109	  }
110	  if (state.onlySelected) list = list.filter(function (e) { return state.selection.has(e.id); });
111	  return list;
112	}
113	function bucketByGroup(ids) {
114	  var order = {};
115	  D.GROUPS.forEach(function (g, i) { order[g.id] = i; });
116	  var map = new Map();
117	  ids.forEach(function (id) {
118	    var e = byId(id); if (!e) return;
119	    if (!map.has(e.groupId)) map.set(e.groupId, []);
120	    map.get(e.groupId).push(e);
121	  });
122	  return Array.from(map.entries())
123	    .sort(function (a, b) { return order[a[0]] - order[b[0]]; })
124	    .map(function (pair) {
125	      return { group: groupById(pair[0]), items: pair[1] };
126	    });
127	}
128	function allTags() {
129	  var s = new Set();
130	  state.entities.forEach(function (e) { e.tags.forEach(function (t) { s.add(t); }); });
131	  return Array.from(s).sort();
132	}
133	
134	/* ================= 渲染：总览 ================= */
135	function render() {
136	  renderStats();
137	  renderTopButtons();
138	  renderTree();
139	  renderBreadcrumb();
140	  renderTable();
141	  renderSelPanel();
142	}
143	
144	function renderStats() {
145	  var counts = {};
146	  STATUS_ORDER.forEach(function (s) { counts[s] = 0; });
147	  var prot = 0;
148	  state.entities.forEach(function (e) {
149	    counts[effective(e).value]++;
150	    if (e.locked) prot++;
151	  });
152	  $('#global-stats').innerHTML =
153	    '<span class="gstat">设备 <b>' + state.entities.length + '</b></span>' +
154	    STATUS_ORDER.map(function (s) {
155	      return '<span class="gstat ' + STATUS_META[s].cls + '">' + STATUS_META[s].label + ' <b>' + counts[s] + '</b></span>';
156	    }).join('') +
157	    '<span class="gstat prot" title="受保护设备在批量写操作中默认跳过">🛡 受保护 <b>' + prot + '</b></span>';
158	}
159	
160	function renderTopButtons() {
161	  $('#btn-undo').disabled = !(state.lastTx && !state.lastTx.undone);
162	  $('#log-count').textContent = state.log.length;
163	}
164	
165	/* ================= 渲染：层级树 ================= */
166	function renderTree() {
167	  var wrap = $('#tree');
168	  wrap.innerHTML = '';
169	  D.GROUPS.filter(function (g) { return !g.parent; })
170	    .forEach(function (g) { wrap.appendChild(treeNode(g, 0)); });
171	}
172	
173	function treeNode(g, depth) {
174	  var node = el('div', 'tree-node');
175	  var kids = D.GROUPS.filter(function (k) { return k.parent === g.id; });
176	  var row = el('div', 'tree-row' + (state.focus === g.id ? ' active' : ''));
177	  row.style.paddingLeft = (8 + depth * 16) + 'px';
178	
179	  var exp = el('button', 'exp' + (kids.length ? '' : ' leaf') + (state.expanded.has(g.id) ? ' open' : ''), '▸');
180	  if (kids.length) {
181	    exp.addEventListener('click', function () {
182	      if (state.expanded.has(g.id)) state.expanded.delete(g.id); else state.expanded.add(g.id);
183	      render();
184	    });
185	  }
186	  row.appendChild(exp);
