402	function applyConfirm() {
403	  var c = state.confirm;
404	  if (!c) return;
405	  var param = c.op === 'tag' ? c.tagText.trim() : c.param;
406	  if (c.op === 'move' && !param) return;
407	  if (c.op === 'tag' && !param) return;
408	  var all = Array.from(state.selection);
409	  var ids = all.filter(function (id) {
410	    var e = byId(id);
411	    return !c.excluded.has(id) && (c.includeProtected || !e.locked);
412	  });
413	  if (!ids.length) return;
414	  var skipped = all.filter(function (id) { return ids.indexOf(id) < 0; });
415	
416	  var tx = executeBatch(c.op, param, ids);
417	  tx.skippedIds = skipped;
418	
419	  state.selection.clear();
420	  state.onlySelected = false;
421	  $('#only-selected').checked = false;
422	  state.confirm = null;
423	  state.result = {
