425	    html: '批量' + OPS[c.op].label + '完成：<b>成功 ' + ids.length + ' 台</b>' +
426	      (skipped.length ? ' · 跳过 ' + skipped.length + ' 台（受保护 / 手动排除）' : '')
427	  };
