371	function executeBatch(op, param, ids) {
372	  var entries = [];
373	  var doomed = [];
374	  ids.forEach(function (id) {
375	    var e = byId(id); if (!e) return;
376	    var idx = state.entities.indexOf(e);
377	    var before = { ownStatus: e.ownStatus, groupId: e.groupId, tags: e.tags.slice() };
378	    if (op === 'status') e.ownStatus = (param === 'clear') ? null : param;
379	    else if (op === 'move') e.groupId = param;
380	    else if (op === 'tag') { if (e.tags.indexOf(param) < 0) e.tags.push(param); }
381	    else if (op === 'delete') doomed.push(e);
382	    entries.push({
383	      id: id, name: e.name, entity: e, index: idx,
384	      before: before,
385	      after: { ownStatus: e.ownStatus, groupId: e.groupId, tags: e.tags.slice() },
386	      deleted: op === 'delete'
387	    });
388	  });
389	  if (op === 'delete') {
390	    state.entities = state.entities.filter(function (e) { return doomed.indexOf(e) < 0; });
391	  }
392	  var tx = {
393	    seq: ++state.txSeq, time: new Date(), op: op, param: param,
394	    opLabel: OPS[op].label + (op === 'delete' ? '' : ' · ' + paramLabelOf(op, param)),
395	    entries: entries, skippedIds: [], undone: false
396	  };
397	  state.log.unshift(tx);
398	  state.lastTx = tx;
399	  return tx;
400	}
